// === Tab: main.js ===
/*
Lines Brush

Author:
  Jason Labbe

Site:
  jasonlabbe3d.com

Controls:
	- Move the mouse to spawn particles.
	- Click to change colors.
*/

var particleLinesPerFrame = 3;
var particlesPerFrame = 2;

var colorScheme = [];
var particles = [];

function setup() {
  let canvas = createCanvas(windowWidth, windowHeight);
	newColorScheme();
}

function draw() {
	blendMode(BLEND);
	background(0);
	blendMode(SCREEN);

	let lastPos = new p5.Vector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	let pos = new p5.Vector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

	// Calculate this frame's velocity.
	let vel = new p5.Vector(pos.x, pos.y);
	vel.sub(lastPos);

	// Spawn sparks.
	for (let i = 0; i < particlesPerFrame; i++) {
		particles.push(new Spark(pos.x, pos.y, vel.x, vel.y));
	}

	// Spawn particles lines.
	vel.normalize();
	for (let i = 0; i < particleLinesPerFrame; i++) {
		particles.push(new ParticleLine(pos.x, pos.y, vel.x, vel.y));
	}

	// Move, draw, and kill all particles.
	for (let i = particles.length - 1; i > -1; i--) {
		particles[i].move();
		particles[i].draw();

		if (particles[i].vel.mag() < 0.1) {
			particles.splice(i, 1);
		}
	}
}

function mouseClicked() {
	newColorScheme();
}

function newColorScheme() {
	colorMode(HSB, 255);

	colorScheme = [];
	let mainHue = random(255);
	let colorCount = 5;

	for (let i = 0; i < colorCount; i++) {
		colorScheme.push(
			color(
				constrain(mainHue + random(-20, 20), 0, 255), 
				map(i, 0, colorCount - 1, 255, 0), 
				255));
	}

	colorMode(RGB, 255);
}

// === Tab: particleLines.js ===
function ParticleLine(x, y, vx, vy) {
	this.startPos = new p5.Vector(x, y);
	this.pos = new p5.Vector(x, y);
	this.vel = new p5.Vector(vx, vy);
	this.vel.mult(random(10));
	this.vel.rotate(radians(random(-25, 25)));
	this.mass = random(1, 30);
	this.airDrag = random(0.92, 0.98);
	this.colorIndex = int(random(colorScheme.length));

	this.move = function() {
		this.vel.mult(this.airDrag);
		this.pos.add(this.vel);
	}

	this.draw = function() {
		let mass = this.mass * this.vel.mag() * 0.6;
		let c = colorScheme[this.colorIndex];
		drawingContext.shadowColor = color(red(c), green(c), blue(c), 255 * this.vel.mag());
		drawingContext.shadowBlur = mass;

		stroke(0);
		strokeWeight(mass);
		line(this.pos.x, this.pos.y, this.startPos.x, this.startPos.y);
	}
}

// === Tab: spark.js ===
function Spark(x, y, vx, vy) {
	this.pos = new p5.Vector(x, y);
	this.lastPos = new p5.Vector(x, y);
	this.vel = new p5.Vector(vx, vy);
	this.vel.rotate(radians(random(-30, 30)));
	this.airDrag = random(0.8, 0.9);

	this.move = function() {
		this.lastPos.set(this.pos.x, this.pos.y);
		this.vel.mult(this.airDrag);
		this.pos.add(this.vel);
	}

	this.draw = function() {
		stroke(255 * this.vel.mag() * 0.2);
		strokeWeight(2);
		line(this.lastPos.x, this.lastPos.y, this.pos.x, this.pos.y);
	}
}

